 await selectText(page,'第 1 段',4,4);await text.press('Enter');const second=page.getByRole('textbox',{name:'第 2 段',exact:true});await expect(second).toBeFocused();await expect(text).toHaveText('项目方案');await expect(second).toHaveText(' 中文😀');await second.press('End');await page.keyboard.insertText(' 继续编写');await second.press('Shift+Enter');await page.keyboard.insertText('换行');await expect(second).toContainText('继续编写\n换行');await selectText(page,'第 2 段',0,0);await second.press('Backspace');await expect(page.getByRole('textbox',{name:'第 2 段',exact:true})).toHaveCount(0);await expect(text).toContainText(' 中文😀');await selectText(page,'第 1 段',4,4);await text.press('Enter');await expect(second).toBeFocused();
 await page.getByRole('tab',{name:'插入',exact:true}).click();await page.getByRole('button',{name:'新建表格',exact:true}).click();const table=page.getByRole('dialog',{name:'新建表格',exact:true});await table.getByRole('button',{name:'插入表格',exact:true}).click();const cell=page.getByRole('textbox',{name:'表格 1 第 1 行第 1 列',exact:true});await cell.fill('表格正文');await page.getByRole('tab',{name:'开始',exact:true}).click();await selectText(page,'表格 1 第 1 行第 1 列',0,4);await page.getByRole('button',{name:'斜体',exact:true}).click();await expect(cell.locator('span')).toHaveCSS('font-style','italic');
 await page.getByRole('button',{name:'新建文件夹',exact:true}).click();const folder=page.getByRole('dialog',{name:'新建文件夹',exact:true});await folder.getByLabel('文件夹名称',{exact:true}).fill('项目资料');await folder.getByRole('button',{name:'保存',exact:true}).click();await list.getByRole('button',{name:'文档操作 项目方案.docx',exact:true}).click();await page.getByRole('menuitem',{name:'移动文档',exact:true}).click();const move=page.getByRole('dialog',{name:'移动文档',exact:true});await move.getByLabel('目标文件夹',{exact:true}).selectOption({label:'项目资料'});await move.getByRole('button',{name:'保存',exact:true}).click();await expect(list.locator('.folder-group').filter({hasText:'项目资料'}).getByRole('button',{name:'项目方案.docx',exact:true})).toBeVisible();
