test('表格断网时行列、格式与单元格编辑保存在本机，刷新后仍在，联网后按顺序提交，冲突停止后续',async({browser,baseURL})=>{
 const owner=await browser.newContext(),member=await browser.newContext();try{
  await collaborationAccount(owner,baseURL!,'owner');await collaborationAccount(member,baseURL!,'member');const space=await(await owner.request.post(baseURL+'/api/cloud/workspaces',{data:{name:'离线表格'}})).json(),invite=await(await owner.request.post(baseURL+'/api/cloud/invite?workspace='+space.id,{data:{email:'member'+collaborationSuffix+'@example.com'}})).json();expect((await member.request.post(baseURL+'/api/cloud/accept',{data:{token:invite.token}})).ok()).toBe(true);
  const resource=await(await owner.request.post(baseURL+'/api/cloud/office-resources?workspace='+space.id,{data:{kind:'spreadsheet',name:'离线.xlsx',mime:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',sourceFormat:'xlsx'}})).json(),a=await owner.newPage(),b=await member.newPage();for(const page of [a,b])await page.goto(baseURL+'/#'+new URLSearchParams({workspace:space.id,doc:resource.id}));
  const cell=(page:Page,r:number,c:number)=>page.getByRole('textbox',{name:`第 ${r} 行第 ${c} 列`,exact:true});await cell(a,1,1).fill('在线内容');await cell(a,1,1).press('Enter');await expect(cell(b,1,1)).toHaveValue('在线内容');
  await a.route('**/office-sheet-operation?**',route=>route.abort('internetdisconnected'));
  await cell(a,1,1).click();await a.getByRole('button',{name:'加粗',exact:true}).click();await a.getByRole('button',{name:'在当前行上方插入',exact:true}).click();await expect(a.getByRole('alert')).toContainText('离线操作');
  await a.getByRole('button',{name:'在当前行上方插入',exact:true}).click();await expect(a.getByRole('alert').filter({hasText:'已有离线行列'})).toBeVisible();
  await cell(a,2,2).fill('离线单元格');await cell(a,2,2).press('Enter');const pending=a.getByRole('region',{name:'离线待提交操作',exact:true});await expect(pending).toContainText('2 个表格操作、1 个单元格');
  await a.reload();await expect(pending).toContainText('2 个表格操作');await expect(cell(b,1,1)).toHaveCSS('font-weight','400');
  await a.unroute('**/office-sheet-operation?**');await pending.getByRole('button',{name:'立即提交',exact:true}).click();await expect(pending).toHaveCount(0);
  await expect(cell(b,2,1)).toHaveValue('在线内容');await expect(cell(b,2,1)).toHaveCSS('font-weight','700');await expect(cell(b,1,1)).toHaveValue('');await expect(cell(b,3,2)).toHaveValue('离线单元格');
  // A structure edit queued against an old layout stops with a conflict and holds back later operations.
  await a.route('**/office-sheet-operation?**',route=>route.abort('internetdisconnected'));await cell(a,1,1).click();await a.getByRole('button',{name:'删除当前行',exact:true}).click();await cell(a,2,1).click();await a.getByRole('button',{name:'斜体',exact:true}).click();await expect(pending).toContainText('2 个表格操作');
  await b.getByRole('button',{name:'新增行',exact:true}).click();await expect(cell(a,4,1)).toBeVisible();
  await a.unroute('**/office-sheet-operation?**');await pending.getByRole('button',{name:'立即提交',exact:true}).click();await expect(pending.getByRole('alert')).toContainText('已更新');await expect(pending).toContainText('后续操作暂停');await expect(cell(b,2,1)).toHaveValue('在线内容');
  await pending.getByRole('button',{name:'按最新结构重新提交',exact:true}).click();await expect(pending).toHaveCount(0);await expect(cell(b,1,1)).toHaveValue('在线内容');await expect(cell(b,1,1)).toHaveCSS('font-style','italic');
 }finally{await owner.close();await member.close();}
});
